inline void servos_mover(Servo& servo, int pin, float angulo, const char* bloque) {
    if (!servo.attached()) servo.attach(pin, 500, 2500);
    if (!servo.attached()) { rb_fail(bloque, "No se pudo activar Servo.h"); return; }
    angulo = fmaxf(0, fminf(180, rb_finite(angulo, bloque)));
    servo.writeMicroseconds(int(500 + angulo * 2000 / 180));
}

